def endpoint_bill(intervals, window_hours, usd_per_replica_hour, replicas=1, requests=0):
    spans = []
    for start, end in intervals:
        stop = window_hours if end is None else min(end, window_hours)
        begin = max(0, start)
        if stop > begin:
            spans.append((begin, stop))
    spans.sort()
    merged = []
    for begin, stop in spans:
        if merged and begin <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], stop))
        else:
            merged.append((begin, stop))
    hours = sum(stop - begin for begin, stop in merged)
    usd = hours * replicas * usd_per_replica_hour
    return {
        "billed_hours": float(hours),
        "usd": float(usd),
        "usd_per_request": (usd / requests) if requests else None,
    }
